/* OCTAVE — native browser research workstation. No runtime dependencies.
   All medical images are fetched from the locally running FastAPI server.
   There is deliberately no simulated patient/demo data. */
(()=>{'use strict';
const $=x=>document.querySelector(x);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ico=(name,size=18)=>{
 const paths={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',layers:'<path d="m12 3-9 5 9 5 9-5-9-5Zm-9 10 9 5 9-5m-18 0 9 5 9-5"/>',wave:'<path d="M2 12h4l3-8 6 16 3-8h4"/>',box:'<path d="m12 2 9 5v10l-9 5-9-5V7l9-5Zm-9 5 9 5 9-5m-9 5v10"/>',folder:'<path d="M3 6h6l2 3h10v11H3z"/>',plus:'<path d="M12 4v16M4 12h16"/>',down:'<path d="M12 2v14m-5-5 5 5 5-5M4 18v4h16v-4"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="3"/><path d="M12 1v4m0 14v4M1 12h4m14 0h4"/>',check:'<path d="m5 12 5 5 9-10"/>',eye:'<path d="M2 12c3-5 6-7 10-7s7 2 10 7c-3 5-6 7-10 7S5 17 2 12Z"/><circle cx="12" cy="12" r="3"/>',settings:'<circle cx="12" cy="12" r="8"/><path d="M12 8v8M8 12h8"/>',back:'<path d="m14 6-6 6 6 6"/>',next:'<path d="m10 6 6 6-6 6"/>',close:'<path d="M5 5 19 19M19 5 5 19"/>',alert:'<path d="M12 3 2 21h20L12 3Zm0 6v5m0 3v1"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',scan:'<path d="M7 3H3v4m14-4h4v4M3 17v4h4m14-4v4h-4M7 12h10"/>',upload:'<path d="m12 16 0-12m-5 5 5-5 5 5M4 17v4h16v-4"/>',info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v6m0-10v1"/>',rotate:'<path d="M3 11a9 9 0 0 1 16-5l2 2m0-5v5h-5M21 13a9 9 0 0 1-16 5l-2-2m0 5v-5h5"/>',spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5L12 2Z"/>'};
 return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.info}</svg>`;
};
const labels={overview:'Workspace',reconstruction:'Reconstruction',vascular:'Vascular analysis',volume:'3D explorer',library:'Studies',methods:'Methods'};
const S={studies:[],id:null,page:'overview',layer:'svc',index:0,overlay:true,vessel:false,threshold:52,seed:null,metric:null,modal:false,uploading:false,progress:0,stage:'',error:'',mode:'v5-v6',seedMode:false,visible:{ilm:true,ipl_inl:true,opl_onl:true,ezc:true,rpe:true},surface:null,yaw:.58,pitch:.62,zoom:1};
const active=()=>S.studies.find(s=>s.id===S.id)||null;
const url=(p='')=>`/api/datasets/${encodeURIComponent(S.id)}${p}`;
const q=()=>`threshold=${S.threshold}${S.seed?`&seed_x=${S.seed.x}&seed_y=${S.seed.y}`:''}`;
const fmt=(n,d=1)=>n==null||!Number.isFinite(Number(n))?'—':Number(n).toLocaleString('en-US',{maximumFractionDigits:d});
const src=(kind)=>kind==='bscan'?url(`/bscan/${S.index}?overlay=${S.overlay}`):S.vessel&&['svc','dvc','cc'].includes(S.layer)?url(`/mask/${S.layer}?${q()}`):url(`/enface/${S.layer}`);
async function api(path,options){const r=await fetch(path,options);if(!r.ok){let msg=await r.text();try{msg=JSON.parse(msg).detail||msg}catch{}throw Error(typeof msg==='string'?msg:JSON.stringify(msg))}return r.json()}
async function refresh(keep=true){const items=await api('/api/datasets');S.studies=items;const existing=keep&&items.some(x=>x.id===S.id);if(!existing){S.id=items[0]?.id||null;S.index=Math.floor((items[0]?.shape?.[0]||1)/2);S.layer=items[0]?.flow_available?'svc':'structural';S.seed=null;S.metric=null}render();await metrics()}
function side(){const nav=[['overview','grid'],['reconstruction','layers'],['vascular','wave'],['volume','box'],['library','folder']];return `<aside class="sidebar"><div class="brand"><div class="brandmark">◈</div><div class="brandtext"><div class="brandname">OCTAVE<span class="mint">.</span></div><div class="brandsub">RETINAL IMAGING</div></div></div><span class="navlabel">WORKSPACE</span><nav class="nav">${nav.map(([key,icon])=>`<button class="${S.page===key?'active':''}" data-page="${key}" title="${labels[key]}">${ico(icon)}<span>${labels[key]}</span></button>`).join('')}</nav><div class="sidebar-foot"><div class="footline"><i class="pulse"></i><span>LOCAL RESEARCH MODE</span></div><small>OCT / OCTA · v0.2<br>Not for clinical diagnosis</small></div></aside>`}
function top(){return `<header class="topbar"><div class="crumb"><span>OCTAVE</span><span>/</span><b>${labels[S.page]}</b></div><div class="toptools"><span class="pill"><i class="pulse"></i> RESEARCH</span><button class="smallbtn icon" data-page="methods" title="Methods and limitations">${ico('info')}</button><button class="smallbtn primary" data-action="upload">${ico('plus',16)} Import scan</button></div></header>`}
function heading(){const map={overview:['Retinal imaging, reimagined.','Anatomy and microvasculature, in one seamless workspace.'],reconstruction:['Reconstruction','Depth-resolved views, from the original volume.'],vascular:['Vascular analysis','Vessel structure and foveal avascular zone.'],volume:['Explore in 3D','The retinal surfaces behind every B-scan.'],library:['Studies','Your local OCT and OCTA workspace.'],methods:['Methods & quality','Transparent reconstruction. Reproducible measurement.']};const [h,p]=map[S.page];return `<div class="herohead"><div><div class="eyebrow">OCT / OCTA RESEARCH STUDIO</div><h1>${h}</h1><p>${p}</p></div>${active()?`<div class="head-actions"><button class="smallbtn" data-action="export">${ico('down',16)} Export</button><button class="smallbtn primary" data-action="upload">${ico('plus',16)} New analysis</button></div>`:''}</div>`}
function empty(){return `<section class="surface empty-shell"><div class="emptycopy"><div class="mini">READY FOR YOUR DATA</div><h2>Every layer.<br>One clear view<span class="mint">.</span></h2><p>Import a structural OCT volume to explore retinal anatomy. Add a registered OCTA flow volume for vascular reconstruction and FAZ analysis.</p><button class="smallbtn primary" data-action="upload">${ico('upload',17)} Import your first scan</button><div class="emptyfoot"><span>${ico('check',14)} Local processing</span><span>${ico('check',14)} No demo patients</span><span>${ico('check',14)} Research exports</span></div></div><div class="empty-visual" aria-hidden="true"><div class="orb-axis"></div><div class="orb-axis v"></div><div class="retina-orb"><i></i><b></b></div></div></section>`}
function studystrip(ds){return `<div class="surface studystrip"><div class="stack"><small>ACTIVE STUDY</small><select id="study-select" class="selectbox" aria-label="Active study">${S.studies.map(st=>`<option value="${esc(st.id)}" ${st.id===S.id?'selected':''}>${esc(st.name)}</option>`).join('')}</select></div><div class="right meta-line"><span>${ico('scan',15)} <strong>${fmt(ds.shape[0],0)}</strong> B-scans</span><span>${fmt(ds.shape[2],0)} × ${fmt(ds.shape[1],0)} px</span><span>${ds.flow_available?'Paired OCTA':'Structural OCT'}</span><span style="color:${ds.preview_sampling?'#e8b87d':'#70c9ad'}">${ds.preview_sampling?'SAMPLED PREVIEW':'FULL RESOLUTION'}</span></div></div>`}
function metric(title,value,unit,sub,accent){return `<div class="surface metric"><div class="cap">${title}<span style="color:${accent}">${ico('spark',17)}</span></div><div class="val">${value}<small>${unit}</small></div><div class="hint">${sub}</div></div>`}
function numbers(ds){const m=S.metric;return `<div class="metric-row">${metric('Vessel density',m?fmt(m.vessel_density_pct,2):'—',m?'%':'',m?'Selected slab · threshold derived':'Flow data required','#60dec1')}${metric('FAZ area',S.layer==='svc'&&m?.faz_detected?fmt(m.faz_area_mm2??m.faz_area_px,m.faz_area_mm2!=null?3:0):'—',S.layer==='svc'&&m?.faz_detected?(m.faz_area_mm2!=null?'mm²':'px²'):'','SVC · if detected','#e9b87e')}${metric('Retinal thickness',fmt(ds.retinal_thickness_um??ds.retinal_thickness_px),ds.retinal_thickness_um!=null?'µm':'px','ILM → RPE · estimated','#ad9bec')}${metric('Boundary QC',ds.qc.any_flagged?'Review':'No flag','','Requires visual confirmation',ds.qc.any_flagged?'#efab75':'#5ce3c6')}</div>`}
function tabs(ds){const layers=[['structural','OCT'],['svc','SVC'],['dvc','DVC'],['avc','AVC'],['cc','CC'],['choroid','Choroid']];return `<div class="tabs" role="tablist" aria-label="En face layer">${layers.filter(([k])=>ds.layers.includes(k)).map(([k,name])=>`<button type="button" role="tab" aria-selected="${S.layer===k}" class="${S.layer===k?'active':''}" data-layer="${k}">${name}</button>`).join('')}</div>`}
function enface(ds){const flow=ds.flow_available&&['svc','dvc','cc'].includes(S.layer);return `<section class="surface"><div class="surface-head"><div><h3>En face</h3><span>${S.layer==='structural'?'Structural reflectance':S.layer==='choroid'?'Choroidal projection':S.layer.toUpperCase()+' projection'}</span></div><button class="smallbtn ghost" data-action="toggle-mask" ${flow?'':'disabled'}>${ico('eye',15)} ${S.vessel?'Mask on':'Vessel mask'}</button></div><div class="pane-media enface"><div class="imageframe ${ds.preview_sampling?'sampled':''}" id="enface-frame"><img id="enface-img" src="${src('enface')}" alt="Reconstructed en face ${esc(S.layer)} image"><div class="crossline" id="crossline"></div></div><div class="imagetag">${esc(S.layer.toUpperCase())} · ${esc(ds.pipeline_mode||'v5-v6')}</div></div><div class="viewer-foot"><div class="plot-top">${tabs(ds)}</div>${flow?`<button class="toggle ${S.seedMode?'active':''}" data-action="seed-mode" title="Click the en face image to select an FAZ seed">${ico('target',15)} ${S.seedMode?'Choose seed':'FAZ seed'}</button>`:''}</div></section>`}
function bscan(ds){return `<section class="surface"><div class="surface-head"><div><h3>Cross-section</h3><span>B-scan anatomy</span></div><button class="toggle ${S.overlay?'active':''}" data-action="toggle-layers">${ico('layers',16)} ${S.overlay?'Layers on':'Layers off'}</button></div><div class="pane-media bscan"><img id="bscan-img" src="${src('bscan')}" alt="Structural OCT B-scan and optional segmentation boundaries"><div class="imagetag">B-SCAN ${String(S.index+1).padStart(3,'0')}</div></div><div class="viewer-foot"><div class="ranges"><button class="smallbtn icon" data-action="prev" title="Previous B-scan">${ico('back')}</button><input id="scan-slider" aria-label="B-scan position" type="range" min="0" max="${ds.shape[0]-1}" step="1" value="${S.index}"><button class="smallbtn icon" data-action="next" title="Next B-scan">${ico('next')}</button><span class="tick">${S.index+1} / ${ds.shape[0]}</span></div></div></section>`}
function inspector(ds){const flow=ds.flow_available&&['svc','dvc','cc'].includes(S.layer),m=S.metric;return `<section id="inspector-card" class="surface"><div class="surface-head"><h3>Analysis</h3><span>${flow?'Threshold-derived':'Structural only'}</span></div><div class="space"><div class="ranges" style="justify-content:space-between"><label class="tiny" for="vessel-range">Vessel threshold</label><span class="tick" id="threshold-label">${S.threshold}th percentile</span></div><div class="ranges" style="margin:13px 0 20px"><input id="vessel-range" type="range" min="1" max="99" value="${S.threshold}" style="width:100%" ${flow?'':'disabled'}></div><div style="display:grid;grid-template-columns:1fr 1fr;gap:12px"><div><div class="tiny">FAZ circularity</div><div style="font-size:21px;font-weight:700;margin-top:9px">${S.layer==='svc'&&m?.faz_detected?fmt(m.faz_circularity,3):'—'}</div></div><div><div class="tiny">Fractal dimension</div><div style="font-size:21px;font-weight:700;margin-top:9px">${m?fmt(m.fractal_dimension,3):'—'}</div></div><div><div class="tiny">Mean caliber</div><div style="font-size:21px;font-weight:700;margin-top:9px">${m?fmt(m.mean_caliber_px_proxy,2):'—'}<small style="color:#749e9a;font-size:11px"> ${m?'px':''}</small></div></div><div><div class="tiny">Seed</div><div style="font-size:14px;font-weight:650;margin-top:14px">${m?.faz_seed?`${m.faz_seed.x}, ${m.faz_seed.y}`:'—'}</div></div></div>${!flow?`<div class="notice">${ico('info',16)} OCTA flow input is required for vessel and FAZ measurements.</div>`:`<p class="hinttext" style="margin-top:22px">Exploratory mask estimates · not validated clinical perfusion.</p>`}</div></section>`}
function chart(){const m=S.metric;return `<div class="surface chart"><div class="chart-head"><h3>Vessel-density profile</h3><small>${m?'Row-wise distribution':'Requires OCTA flow data'}</small></div><canvas id="density" aria-label="Vessel density by scan position"></canvas></div>`}
function warnings(ds){return `<details class="qc-panel"><summary>${ico('alert',15)} QC & method notes <span>${(ds.warnings||[]).length} items</span></summary><div class="warninglist">${(ds.warnings||[]).map(w=>`<div class="warning">${esc(w)}</div>`).join('')}</div></details>`}
function workbook(ds){return `${studystrip(ds)}${numbers(ds)}<div class="gridwork"><div class="mainpanels">${enface(ds)}${chart()}</div><div class="mainpanels">${bscan(ds)}${inspector(ds)}</div></div>${warnings(ds)}`}
function list(){return `<div class="surface space">${S.studies.map(ds=>`<div class="study-card" data-study="${esc(ds.id)}"><div class="thumb">${ico('layers',22)}</div><div><strong>${esc(ds.name)}</strong><p>${ds.shape[0]} frames · ${ds.shape[1]} × ${ds.shape[2]} · ${ds.flow_available?'Structural + flow':'Structural OCT'} · ${esc(ds.pipeline_mode||'v5-v6')}</p></div><span class="arrow">${ico('next')}</span></div>`).join('')||`<div class="empty-state"><h3>No studies yet</h3><p>Import a scan to populate this library.</p><button class="smallbtn primary" data-action="upload">${ico('upload')} Import scan</button></div>`}</div>`}
function methods(){return `<section class="surface space" style="max-width:860px;padding:30px"><div class="eyebrow">TRANSPARENT METHODS</div><h2 style="font-size:27px;letter-spacing:-.04em;margin:8px 0 26px">Original v5 pipeline, v6 analysis.</h2><div class="warninglist"><div class="warning"><b style="color:#e4f5ed">Boundaries</b><p>Original supplied dynamic-programming retinal tracing is the default. The v6 EZC boundary is available for inspection; OPL/ONL remains an estimate. Fast segmentation is an explicitly selected preview only.</p></div><div class="warning"><b style="color:#e4f5ed">Flow reconstruction</b><p>Provided v5 despeckling, bulk-motion correction, projection/shadow suppression, row flat-field, Frangi/CLAHE enhancement, and avascular void display. Flow must be paired and co-registered.</p></div><div class="warning"><b style="color:#e4f5ed">FAZ & vessels</b><p>FAZ follows the supplied v6 enclosed non-vessel component method, with closings at 5, 3, and 2 pixels. Mask threshold and seed are adjustable. Pixel-derived vessel morphometry requires expert validation on new datasets.</p></div><div class="warning"><b style="color:#e4f5ed">Choroid</b><p>Default choroid reconstruction uses the original v5 RPE-offset estimate. Optional Choroidalyzer boundaries require an independently installed pretrained model and configured inference. Proxy regions are always identified.</p></div><div class="warning"><b style="color:#e4f5ed">Calibration & privacy</b><p>Physical units are shown only with supplied acquisition calibration. Uploaded volumes remain on the local API server; never expose the service without authentication and security review. Not for clinical diagnosis.</p></div></div></section>`}
function three(ds){const names=[['ilm','#ff8e96'],['ipl_inl','#e8ba77'],['opl_onl','#57e8cc'],['ezc','#bb9cf4'],['rpe','#79c69e']];return `${studystrip(ds)}<div class="surface"><div class="surface-head"><div><h3>Retinal surface explorer</h3><span>Drag to rotate · scroll to zoom</span></div><button class="smallbtn ghost" data-action="reset3d">${ico('rotate')} Reset view</button></div><div class="three-stage"><canvas id="surface3d"></canvas><div class="imagetag">ANATOMICAL SURFACES · ${esc(ds.pipeline_mode||'v5-v6')}</div></div><div class="legend">${names.map(([k,color])=>`<label><input type="checkbox" data-boundary="${k}" ${S.visible[k]?'checked':''}><i class="swatch" style="background:${color}"></i>${k.toUpperCase().replace('_','/')}</label>`).join('')}</div></div><p class="workspace-note">3D heightfield depicts OCT-estimated tissue boundaries, not a segmented vascular tree.</p>${warnings(ds)}`}
function modal(){return `<div class="modal-back" id="modal-back"><form class="modal" id="upload-form"><div class="modal-head"><div><div class="eyebrow" style="margin-bottom:8px">NEW ANALYSIS</div><h2>Import OCT volume</h2></div><button class="smallbtn icon" type="button" data-action="close">${ico('close')}</button></div><div class="modal-body"><div class="form-field"><label for="ds-name">Study label</label><input id="ds-name" name="name" type="text" value="New OCT study" maxlength="120" required></div><div class="form-field"><label>Structural OCT · required</label><div class="filefield">${ico('upload')}<span id="file-s-name">Choose ZIP / NPY / NPZ / TIFF<small>Numbered B-scans or a volume array</small></span><input name="structural" id="structural-file" type="file" accept=".zip,.npy,.npz,.tif,.tiff" required></div></div><div class="form-field"><label>Paired flow / OCTA · optional</label><div class="filefield">${ico('wave')}<span id="file-f-name">Add registered OCTA flow volume<small>Required for vessel and FAZ analysis</small></span><input name="flow" id="flow-file" type="file" accept=".zip,.npy,.npz,.tif,.tiff"></div></div><div class="field2"><div class="form-field"><label>Pipeline</label><select name="mode"><option value="v5-v6">v5 reconstruction + v6 analysis</option><option value="preview">Fast exploratory preview</option></select></div><div class="form-field"><label>Processing</label><select name="max_slices"><option value="0">Full volume</option><option value="128">Sample 128 B-scans</option><option value="64">Sample 64 B-scans</option></select></div></div><div class="field3"><div class="form-field"><label>Width (mm)</label><input name="fov_x_mm" type="number" min="0.01" max="60" step="any" placeholder="Optional"></div><div class="form-field"><label>Height (mm)</label><input name="fov_y_mm" type="number" min="0.01" max="60" step="any" placeholder="Optional"></div><div class="form-field"><label>Axial (µm/px)</label><input name="axial_um_per_px" type="number" min="0.001" max="50" step="any" placeholder="Optional"></div></div><div class="hinttext">Only enter verified scan calibration. Full v5 segmentation may be computationally intensive for large datasets.</div>${S.error?`<div class="errorbox">${esc(S.error)}</div>`:''}${S.uploading?`<div class="progress"><span style="width:${Math.round(S.progress*100)}%"></span></div><div class="progress-label">${esc(S.stage)}</div>`:''}<div class="form-footer"><button type="button" class="smallbtn" data-action="close" ${S.uploading?'disabled':''}>Cancel</button><button type="submit" class="smallbtn primary" ${S.uploading?'disabled':''}>${ico('spark',16)} ${S.uploading?'Processing…':'Reconstruct volume'}</button></div></div></form></div>`}
function paintChart(){const canvas=$('#density');if(!canvas)return;const ctx=canvas.getContext('2d');const w=canvas.width=Math.max(250,canvas.clientWidth*devicePixelRatio),h=canvas.height=160*devicePixelRatio;ctx.scale(devicePixelRatio,devicePixelRatio);const W=w/devicePixelRatio,H=h/devicePixelRatio;ctx.clearRect(0,0,W,H);const m=S.metric;ctx.strokeStyle='#263945';ctx.lineWidth=1;for(let i=0;i<=4;i++){const y=12+i*(H-25)/4;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}if(!m?.row_density_pct?.length)return;const data=m.row_density_pct;const max=Math.max(1,Math.max(...data)*1.15);const pts=data.map((v,i)=>[i/(data.length-1)*W,H-14-v/max*(H-30)]);const grd=ctx.createLinearGradient(0,15,0,H);grd.addColorStop(0,'#65dec955');grd.addColorStop(1,'#65dec902');ctx.beginPath();ctx.moveTo(0,H-14);pts.forEach(([x,y])=>ctx.lineTo(x,y));ctx.lineTo(W,H-14);ctx.closePath();ctx.fillStyle=grd;ctx.fill();ctx.beginPath();pts.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.strokeStyle='#6fe8cc';ctx.lineWidth=2;ctx.stroke()}
function crossline(){const el=$('#crossline'),img=$('#enface-img'),ds=active();if(!el||!img||!ds)return;const box=img.getBoundingClientRect();const frame=el.parentElement.getBoundingClientRect();const naturalW=img.naturalWidth||ds.shape[2],naturalH=img.naturalHeight||ds.shape[0];const sampled=ds.preview_sampling;const scale=Math.min(box.width/naturalW,box.height/naturalH);const imgh=sampled?box.height:naturalH*scale;const imw=sampled?box.width:naturalW*scale;const top=sampled?0:(box.height-imgh)/2;el.style.left=((box.width-imw)/2)+'px';el.style.right='auto';el.style.width=imw+'px';el.style.top=(top+(S.index+.5)/ds.shape[0]*imgh)+'px'}
function syncImages(){const im=$('#enface-img'),bs=$('#bscan-img');if(im)im.src=src('enface')+'&v='+(S.vessel?S.threshold:'0');if(bs)bs.src=src('bscan');if(im){im.onload=crossline;crossline()}const range=$('#scan-slider');if(range)range.value=S.index;const tick=$('.tick');if(tick&&range)tick.textContent=`${S.index+1} / ${active().shape[0]}`}
function plot3d(){
 const canvas=$('#surface3d');if(!canvas||!S.surface)return;
 const rect=canvas.getBoundingClientRect(),dpr=devicePixelRatio||1,ctx=canvas.getContext('2d');
 canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr);
 ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,rect.width,rect.height);
 const mesh=S.surface.layers,keys=Object.keys(mesh).filter(k=>S.visible[k]);
 if(!keys.length)return;
 const values=Object.values(mesh).flat(2).filter(Number.isFinite);
 const lo=Math.min(...values),hi=Math.max(...values),range=Math.max(1,hi-lo);
 const rows=mesh.ilm.length,cols=mesh.ilm[0].length;
 const scale=Math.min(rect.width*.33,rect.height*.40)*S.zoom;
 const point=(i,j,z)=>{
   const x=(j/Math.max(1,cols-1)-.5)*2.05;
   const y=(i/Math.max(1,rows-1)-.5)*2.05;
   const v=-(z-lo)/range*1.0;
   const xr=x*Math.cos(S.yaw)+y*Math.sin(S.yaw);
   const yr=-x*Math.sin(S.yaw)+y*Math.cos(S.yaw);
   const hz=yr*Math.cos(S.pitch)-v*Math.sin(S.pitch);
   return [rect.width*.50+xr*scale,rect.height*.50+hz*scale];
 };
 const glow=ctx.createRadialGradient(rect.width/2,rect.height/2,4,rect.width/2,rect.height/2,rect.width*.48);
 glow.addColorStop(0,'rgba(33,145,124,.16)');glow.addColorStop(1,'rgba(0,0,0,0)');
 ctx.fillStyle=glow;ctx.fillRect(0,0,rect.width,rect.height);
 const palette={ilm:'#ff8e96',ipl_inl:'#e8ba77',opl_onl:'#57e8cc',ezc:'#bb9cf4',rpe:'#79c69e'};
 for(const key of [...keys].reverse()){
   const grid=mesh[key],color=palette[key]||'#a1dfd0';
   ctx.save();ctx.strokeStyle=color;ctx.lineJoin='round';ctx.lineCap='round';
   const rowStride=Math.max(1,Math.floor(rows/34));
   for(let i=0;i<rows;i+=rowStride){
     ctx.beginPath();for(let j=0;j<cols;j++){
       const xy=point(i,j,grid[i][j]);if(j===0)ctx.moveTo(xy[0],xy[1]);else ctx.lineTo(xy[0],xy[1]);
     }
     ctx.globalAlpha=.62;ctx.lineWidth=1.2;ctx.stroke();
   }
   const colStride=Math.max(1,Math.floor(cols/32));
   for(let j=0;j<cols;j+=colStride){
     ctx.beginPath();for(let i=0;i<rows;i++){
       const xy=point(i,j,grid[i][j]);if(i===0)ctx.moveTo(xy[0],xy[1]);else ctx.lineTo(xy[0],xy[1]);
     }
     ctx.globalAlpha=.36;ctx.lineWidth=.85;ctx.stroke();
   }
   ctx.globalAlpha=.9;ctx.lineWidth=1.8;
   for(const i of [0,rows-1]){
     ctx.beginPath();for(let j=0;j<cols;j++){
       const xy=point(i,j,grid[i][j]);if(j===0)ctx.moveTo(xy[0],xy[1]);else ctx.lineTo(xy[0],xy[1]);
     }ctx.stroke();
   }
   ctx.restore();
 }
}
function register3d(){const cv=$('#surface3d');if(!cv)return;let drag=false,x=0,y=0;cv.onpointerdown=e=>{drag=true;x=e.clientX;y=e.clientY;cv.setPointerCapture(e.pointerId)};cv.onpointerup=()=>drag=false;cv.onpointermove=e=>{if(!drag)return;S.yaw+=(e.clientX-x)*.006;S.pitch=Math.max(.13,Math.min(1.35,S.pitch+(e.clientY-y)*.005));x=e.clientX;y=e.clientY;plot3d()};cv.onwheel=e=>{e.preventDefault();S.zoom=Math.max(.45,Math.min(2.6,S.zoom-e.deltaY*.0008));plot3d()};window.addEventListener('resize',plot3d,{once:true})}
async function surface(){if(S.page!=='volume'||!S.id)return;const id=S.id;try{S.surface=await api(url('/surface?step=9'));if(id!==S.id)return;plot3d();register3d()}catch(e){showError(e.message)}}
async function metrics(){const ds=active();if(!ds?.flow_available||!['svc','dvc','cc'].includes(S.layer)){S.metric=null;updateMetrics();return}const id=S.id,layer=S.layer,threshold=S.threshold,seed=S.seed;try{const m=await api(url(`/analyze/${layer}?${q()}`));if(id!==S.id||layer!==S.layer||threshold!==S.threshold||seed!==S.seed)return;S.metric=m;updateMetrics();}catch(e){S.metric=null;updateMetrics();showError(e.message)}}
function updateMetrics(){const ds=active();if(!ds)return;for(const [sel,html] of [['.metric-row',numbers(ds)],['#inspector-card',inspector(ds)]]){const el=$(sel);if(el)el.outerHTML=html}const chartLabel=$('.chart-head small');if(chartLabel)chartLabel.textContent=S.metric?'Row-wise distribution':'Requires OCTA flow data';paintChart()}
function showError(msg){S.error=msg;const old=$('.errorbox');if(old)old.textContent=msg;else{const el=document.createElement('div');el.className='errorbox';el.textContent=msg;$('.main')?.prepend(el)}}
function render(){const ds=active();let body;if(S.page==='methods')body=methods();else if(S.page==='library')body=list();else if(!ds)body=empty();else if(S.page==='volume')body=three(ds);else body=workbook(ds);$('#app').innerHTML=`<div class="app">${side()}<div class="shell">${top()}<main class="main">${heading()}${body}<div class="workspace-note">OCTAVE 0.2 · Research use only · Local processing</div></main></div></div>${S.modal?modal():''}`;paintChart();const im=$('#enface-img');if(im)im.onload=crossline;crossline();if(S.page==='volume')surface()}
async function upload(form){if(S.uploading)return;S.error='';const fd=new FormData(form);for(const k of ['fov_x_mm','fov_y_mm','axial_um_per_px'])if(!fd.get(k))fd.delete(k);S.uploading=true;S.stage='Uploading volume';S.progress=.03;render();try{const job=await api('/api/datasets',{method:'POST',body:fd});let state=job;while(state.status==='processing'){await new Promise(res=>setTimeout(res,800));state=await api(`/api/jobs/${job.id}`);S.progress=state.progress;S.stage=state.stage;const bar=$('.progress span');if(bar)bar.style.width=Math.round(S.progress*100)+'%';const text=$('.progress-label');if(text)text.textContent=S.stage}if(state.status==='failed')throw Error(state.error||'Reconstruction failed');S.modal=false;S.uploading=false;S.page='overview';await refresh(false);S.id=state.dataset_id;S.index=Math.floor(active()?.shape?.[0]/2)||0;S.seed=null;S.layer='svc';S.metric=null;render();await metrics()}catch(e){S.uploading=false;S.error=e.message;render()}}
let throttle;document.addEventListener('input',e=>{if(e.target.id==='scan-slider'){S.index=+e.target.value;const ds=active();if(!ds)return;const scan=$('#bscan-img');if(scan)scan.src=src('bscan');crossline();const el=e.target.parentElement.querySelector('.tick');if(el)el.textContent=`${S.index+1} / ${ds.shape[0]}`}if(e.target.id==='vessel-range'){S.threshold=+e.target.value;const l=$('#threshold-label');if(l)l.textContent=`${S.threshold}th percentile`;clearTimeout(throttle);throttle=setTimeout(()=>{metrics();const im=$('#enface-img');if(im&&S.vessel)im.src=src('enface')},300)}});
document.addEventListener('change',e=>{if(e.target.id==='study-select'){S.id=e.target.value;const ds=active();S.index=Math.floor(ds.shape[0]/2);S.layer=ds.flow_available?'svc':'structural';S.metric=null;S.seed=null;render();metrics()}if(e.target.dataset.boundary){S.visible[e.target.dataset.boundary]=e.target.checked;plot3d()}if(e.target.id==='structural-file'||e.target.id==='flow-file'){const t=$(e.target.id==='structural-file'?'#file-s-name':'#file-f-name');if(t)t.textContent=e.target.files?.[0]?.name||'Choose volume'}});
document.addEventListener('submit',e=>{if(e.target.id==='upload-form'){e.preventDefault();upload(e.target)}});
document.addEventListener('click',async e=>{const enface=e.target.closest('#enface-img');if(enface){const ds=active();if(!ds)return;const rect=enface.getBoundingClientRect(),ratio=Math.min(rect.width/enface.naturalWidth,rect.height/enface.naturalHeight),w=enface.naturalWidth*ratio,h=enface.naturalHeight*ratio,ox=(rect.width-w)/2,oy=(rect.height-h)/2;const x=Math.floor((e.clientX-rect.left-(ds.preview_sampling?0:ox))/(ds.preview_sampling?rect.width:w)*ds.shape[2]),y=Math.floor((e.clientY-rect.top-(ds.preview_sampling?0:oy))/(ds.preview_sampling?rect.height:h)*ds.shape[0]);if(x<0||y<0||x>=ds.shape[2]||y>=ds.shape[0])return;if(S.seedMode&&ds.flow_available){S.seed={x,y};S.seedMode=false;const im=$('#enface-img');if(im&&S.vessel)im.src=src('enface');await metrics();render()}else{S.index=y;const scan=$('#bscan-img');if(scan)scan.src=src('bscan');const range=$('#scan-slider');if(range)range.value=y;crossline();const tick=$('.tick');if(tick)tick.textContent=`${y+1} / ${ds.shape[0]}`}return}
 const study=e.target.closest('[data-study]');if(study){S.id=study.dataset.study;S.page='overview';S.layer=active().flow_available?'svc':'structural';S.index=Math.floor(active().shape[0]/2);S.seed=null;S.metric=null;render();metrics();return}
 const page=e.target.closest('[data-page]');if(page){S.page=page.dataset.page;S.error='';render();return}
 const layer=e.target.closest('[data-layer]');if(layer){S.layer=layer.dataset.layer;S.metric=null;S.vessel=false;render();metrics();return}
 const el=e.target.closest('[data-action]');if(!el)return;switch(el.dataset.action){case'upload':S.modal=true;S.error='';render();break;case'close':if(!S.uploading){S.modal=false;S.error='';render()}break;case'export':if(S.id)window.location.href=url(`/export?${q()}`);break;case'toggle-layers':S.overlay=!S.overlay;render();break;case'toggle-mask':S.vessel=!S.vessel;render();break;case'seed-mode':S.seedMode=!S.seedMode;render();break;case'prev':S.index=Math.max(0,S.index-1);render();break;case'next':S.index=Math.min(active().shape[0]-1,S.index+1);render();break;case'reset3d':S.yaw=.58;S.pitch=.62;S.zoom=1;plot3d();break;}});
refresh().catch(e=>{S.error=e.message;$('#app').innerHTML=`<div class="empty-state" style="min-height:100vh;display:grid;place-content:center"><h3>Cannot reach the analysis server</h3><p>${esc(e.message)}</p><code>cd backend && uvicorn app.main:app --reload</code></div>`});
})();
